package com.example

import com.example.ExamQuestionHelper.QSpec

object MusicLiveExamHistoryMusiciansBank1 {
    private const val T = "ශ්‍රී ලාංකේය හා භාරතීය සංගීතවේදීන් හා සංගීත ඉතිහාසය"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("භාරතීය සංගීත ඉතිහාසයේ සංගීතයේ ආරම්භක මූලාශ්‍රය ලෙස සැලකෙන වේද ග්‍රන්ථය කුමක්ද?", "සාම වේදය", "සෘග් වේදය", "යජුර් වේදය", "අථර්ව වේදය", "සෘග්වේදීය මන්ත්‍ර ස්වර තුනකින් හා පසුව සප්ත ස්වරයෙන් ගායනා කිරීම සාම වේදයෙන් ආරම්භ විය."),
        q("භාරතීය නාට්‍ය, නර්තන හා සංගීත ශාස්ත්‍රය පිළිබඳ පුරාණතම ග්‍රන්ථය වන 'නාට්‍ය ශාස්ත්‍රය' රචනා කළේ කවුද?", "භරතමුනි", "ශාර්ංගදේව", "මතංගමුනි", "නාරදමුනි", "ක්‍රි.පූ. 2 හා ක්‍රි.ව. 2 සියවස් අතර කාලයේ භරතමුනි විසින් නාට්‍ය ශාස්ත්‍රය රචනා කරන ලදී."),
        q("උත්තර හා දක්ෂිණ භාරතීය සංගීත පද්ධති දෙකම වෙන් වීමට පෙර 13 වන සියවසේදී රචිත 'සංගීත රත්නාකරය' කාගේ කෘතියක්ද?", "ශාර්ංගදේව පඬිතුමාගේ", "භරතමුනිගේ", "අමීර් ඛුස්රෝගේ", "ලෝචන පඬිතුමාගේ", "හින්දුස්ථානි හා කර්ණාටක පද්ධති දෙකටම මූලාශ්‍ර වූ සංගීත රත්නාකරය ශාර්ංගදේව විසින් රචනා කෙරිණි."),
        q("'රාග' යන වචනය සහ රාග ලක්ෂණ ප්‍රථම වරට ශාස්ත්‍රීයව විග්‍රහ කළ 'බෘහද්දේශී' ග්‍රන්ථයේ කර්තෘ කවුද?", "මතංගමුනි", "භරතමුනි", "ජයදේව", "වෙන්කටමුඛී", "මතංගමුනි විසින් රචිත බෘහද්දේශී කෘතියෙහි රාග සංකල්පය මුල් වරට පැහැදිලි කෙරිණි."),
        q("12 වන සියවසේ සුප්‍රකට 'ගීත ගෝවින්දය' රචනා කළ සංස්කෘත කවියා හා සංගීතඥයා කවුද?", "ජයදේව", "කාලිදාස", "තාන්සේන්", "අහෝබල", "ශ්‍රී ජයදේව කවියාගේ ගීත ගෝවින්දයේ ඇති අෂ්ටපදී ගීත භාරතීය සංගීතයේ අදටත් ගැයේ."),
        q("භාරතීය සංගීත ඉතිහාසයේ තුර්කි-පර්සියානු ආභාසය එක්කරමින් සිතාරය හා තබ්ලාව බිහි කළේ යැයි සැලකෙන්නේ කවුද?", "අමීර් ඛුස්රෝ", "මියාන් තාන්සේන්", "ස්වාමි හරිදාස්", "බෛජු බව්රා", "අලාඋද්දීන් ඛිල්ජි රජුගේ සභාවේ සිටි අමීර් ඛුස්රෝ කව්වාලි, තරානා සහ නව රාග බිහි කළේය."),
        q("රාග ගායන සම්ප්‍රදායේ එන 'තරානා' (Tarana) සහ 'කව්වාලි' යන ගායන විධිවල නිර්මාතෘ කවුද?", "අමීර් ඛුස්රෝ", "ශාර්ංගදේව", "පණ්ඩිත් භාත්ඛණ්ඩේ", "රබීන්ද්‍රනාත් තාගෝර්", "පර්සියානු හා භාරතීය ශෛලීන් මුසු කරමින් අමීර් ඛුස්රෝ තරානා ගායන ක්‍රමය හඳුන්වා දුන්නේය."),
        q("මෝගල් අධිරාජ්‍යයා වූ අක්බර් රජුගේ රාජ සභාවේ නව රත්නයන්ගෙන් එක් අයෙකු වූ මහා සංගීතඥයා කවුද?", "මියාන් තාන්සේන්", "භරතමුනි", "විෂ්ණු දිගම්බර පලුස්කර්", "පණ්ඩිත් රවි ශංකර්", "රාම් තනු පාණ්ඩේ නමින් උපන් තාන්සේන් අක්බර් අධිරාජ්‍යයාගේ සභාවේ ප්‍රධාන සංගීතඥයා විය."),
        q("මියාන් තාන්සේන් සංගීතය හැදෑරූ ඔහුගේ විශිෂ්ට සංගීත ගුරුවරයා කවුද?", "ස්වාමි හරිදාස්", "අමීර් ඛුස්රෝ", "වෙන්කටමුඛී", "මතංගමුනි", "වෘන්දාබන්හි විසූ භක්තිමත් සංගීත ඍෂිවරයෙකු වූ ස්වාමි හරිදාස් තාන්සේන්ගේ ගුරුවරයාය."),
        q("මියාන් තාන්සේන් විසින් නිර්මාණය කරන ලද සුප්‍රසිද්ධ රාග යුගලයක් නම් කරන්න.", "මියාන් කි මල්හාර් සහ දර්බාරි කානඩා", "භූපාලි සහ බිලාවල්", "කාෆි සහ ඛමාජ්", "භෛරව් සහ යමන්", "තාන්සේන්ගේ නාමයෙන් බිහිවූ මියාන් කි තෝඩි, මියාන් කි මල්හාර් හා දර්බාරි කානඩා ප්‍රකටය."),
        q("තාන්සේන්ගේ රාග අතරින් 'දීපක්' රාගය ගැයූ විට ඇතිවූ අධික තාපය සමනය කිරීමට ගැයූ රාගය ලෙස ජනප්‍රවාදයේ සඳහන් වන්නේ කුමක්ද?", "මල්හාර් (මේඝ මල්හාර්)", "භෛරවී", "භූපාලි", "යමන්", "වැසි වස්සවන මල්හාර් රාගය ගයා දීපක් රාගයේ ගිනි රස්නය නිවා දැමූ බව ජනප්‍රවාදයේ එයි."),
        q("මහා සංගීතඥ මියාන් තාන්සේන් සමඟ සම්බන්ධ 'සේනියා ඝරානාව' බිහිවූයේ කවර සම්ප්‍රදායක් ආශ්‍රයෙන්ද?", "ධ්‍රැපද් හා රබාබ්/සිතාර් සම්ප්‍රදාය", "බටහිර සිම්ෆනි සම්ප්‍රදාය", "කෝලම් හා සොකරි සම්ප්‍රදාය", "ජපන් නෝ සම්ප්‍රදාය", "තාන්සේන්ගේ පරපුරෙන් පැවත ආ සංගීත ගුරු කුලය සේනියා ඝරානාව ලෙස ප්‍රකට විය."),
        q("17 වන සියවසේදී 'චතුර්දණ්ඩි ප්‍රකාශිකා' ග්‍රන්ථය ලියා දක්ෂිණ භාරතීය 72 මේලකර්තා පද්ධතිය සැකසූයේ කවුද?", "වෙන්කටමුඛී", "ලෝචන", "ශාර්ංගදේව", "භාත්ඛණ්ඩේ", "ස්වර 12 ඇසුරෙන් ගණිතමය ලෙස මේලකර්තා 72ක් වෙන්කටමුඛී විසින් සකසන ලදී."),
        q("නූතන උත්තර භාරතීය සංගීතයේ 'ථාට දහය' හා ස්වරලිපි ක්‍රමය ක්‍රමවත්ව පිහිටුවූ විද්වතා කවුද?", "පණ්ඩිත් විෂ්ණු නාරායන් භාත්ඛණ්ඩේ", "පණ්ඩිත් විෂ්ණු දිගම්බර පලුස්කර්", "මියාන් තාන්සේන්", "අමීර් ඛුස්රෝ", "පණ්ඩිත් වී. එන්. භාත්ඛණ්ඩේ නූතන ථාට 10 ක්‍රමය සහ හින්දුස්ථානි සංගීත පද්ධති ග්‍රන්ථ රචනා කළේය."),
        q("පණ්ඩිත් විෂ්ණු නාරායන් භාත්ඛණ්ඩේ රචනා කළ සුප්‍රසිද්ධ සංගීත ග්‍රන්ථ මාලාව කුමක්ද?", "හින්දුස්ථානි සංගීත පද්ධති ග්‍රන්ථ මාලාව", "භරතමුනිගේ නාට්‍ය ශාස්ත්‍ර ග්‍රන්ථය", "ශාර්ංගදේවගේ සංගීත රත්නාකර ග්‍රන්ථය", "සුනිල් ශාන්තගේ හෙළ මිහිර ග්‍රන්ථය", "ඉන්දියාව පුරා සංචාරය කර ගුරු කුල රාග එක්රැස් කර ක්‍රමික් පුස්තක් මාලිකා ලියා තැබීය."),
        q("භාත්ඛණ්ඩේතුමා විසින් ආරම්භ කරන ලද ප්‍රකට සංගීත විද්‍යාලය පිහිටියේ ඉන්දියාවේ කුමන නගරයේද?", "ලක්නව් නගරයේ", "කොළඹ නගරයේ", "මදුරාසි නගරයේ", "බැංගලෝර් නගරයේ", "ලක්නව්හි Marris College of Music (වත්මන් භාත්ඛණ්ඩේ සංගීත විද්‍යාපීඨය) පිහිටුවීය."),
        q("ශ්‍රී ලංකාවේ බොහෝ සංගීත විද්වතුන් උසස් සංගීත උපාධි ලබාගැනීමට ගිය භාත්ඛණ්ඩේ විශ්වවිද්‍යාලය හරහා අපට ලැබුණේ කුමක්ද?", "විද්‍යානුකූල ථාට රාග පද්ධතිය හා ස්වරලිපි ක්‍රමය", "බටහිර ඔපෙරා පුහුණුව පමණක්", "කර්ණාටක 72 මේල ක්‍රමය", "ගැමි කෝලම් නැටුම් ක්‍රමය", "පාසල් හා විශ්වවිද්‍යාල විෂය නිර්දේශයට භාත්ඛණ්ඩේ ක්‍රමය සෘජුවම පදනම් වී ඇත."),
        q("භාත්ඛණ්ඩේතුමාගේ සමකාලීනයෙකු ලෙස භාරතීය සංගීතය පොදු ජනතාව අතරට ගෙන ගිය සංගීතඥයා කවුද?", "පණ්ඩිත් විෂ්ණු දිගම්බර පලුස්කර්", "මියාන් තාන්සේන්", "භරතමුනි", "පිලිප්පු සිංඤෝ", "පණ්ඩිත් පලුස්කර් 1901 දී ගාන්ධර්ව මහාවිද්‍යාලය පිහිටුවා සංගීත අධ්‍යාපනය විවෘත කළේය."),
        q("පණ්ඩිත් විෂ්ණු දිගම්බර පලුස්කර් විසින් ලාහෝර් නුවර පිහිටුවන ලද ප්‍රථම පොදු සංගීත ආයතනය කුමක්ද?", "ගාන්ධර්ව මහාවිද්‍යාලය", "ශාන්තිනිකේතනය", "ටවර් හෝල් රඟහල", "කලාභූමි", "රජ මැදුරුවලට සීමා වූ සංගීතය සාමාන්‍ය ශිෂ්‍යයන්ට ඉගැන්වීමට ගාන්ධර්ව මහාවිද්‍යාලය පිහිටුවීය."),
        q("'රඝුපති රාඝව රාජාරාම්' යන භජන් ගීතය අද අසන ජනප්‍රිය නාද රටාවට සැකසූ සංගීතඥයා කවුද?", "විෂ්ණු දිගම්බර පලුස්කර්", "රවි ශංකර්", "ආනන්ද සමරකෝන්", "විශ්වනාත් ලෞජි", "මහත්මා ගාන්ධිතුමාගේ ප්‍රියතම භජන් ගීතය වූ මෙය පලුස්කර්තුමා ප්‍රචලිත කළේය."),
        q("නොබෙල් ත්‍යාගලාභී මහා කවි රබීන්ද්‍රනාත් තාගෝර්තුමා පිහිටුවූ ප්‍රසිද්ධ කලා හා සංගීත නිකේතනය කුමක්ද?", "ශාන්තිනිකේතනය (විශ්ව භාරතී)", "මැරිස් විද්‍යාලය", "ගාන්ධර්ව මහාවිද්‍යාලය", "හෙළ හවුල", "බෙංගාලයේ බෝල්පූර්හි පිහිටි ශාන්තිනිකේතනය ශ්‍රී ලාංකික කලාකරුවන් රැසකටද තෝතැන්නක් විය."),
        q("රබීන්ද්‍රනාත් තාගෝර්තුමා නිර්මාණය කළ දෙදහසකට අධික ගීත සමුදාය හඳුන්වනු ලබන්නේ කුමන නමින්ද?", "රබීන්ද්‍ර සංගීතය", "කර්ණාටක සංගීතය", "නූර්ති සංගීතය", "තප්පා සංගීතය", "භාරතීය රාග, බෙංගාලි ජන ගී හා සරල ගී ඇසුරෙන් බිහිවූ ඒවා රබීන්ද්‍ර සංගීතය වේ."),
        q("භාරතයේ ජාතික ගීය වන 'ජන ගණ මන' රචනා කර තනු නිර්මාණය කළේ කවුද?", "රබීන්ද්‍රනාත් තාගෝර්", "විෂ්ණු නාරායන් භාත්ඛණ්ඩේ", "අමීර් ඛුස්රෝ", "පණ්ඩිත් රවි ශංකර්", "රබීන්ද්‍රනාත් තාගෝර්තුමා ඉන්දියාවේ හා බංග්ලාදේශයේ ජාතික ගීතවල නිර්මාතෘවරයාය."),
        q("ශාන්තිනිකේතනයේ අධ්‍යාපනය ලබා ශ්‍රී ලංකාවට පැමිණ ශ්‍රී ලංකා ජාතික ගීය නිර්මාණය කළ සංගීතඥයා කවුද?", "ආනන්ද සමරකෝන්", "සුනිල් ශාන්ත", "ඩබ්ලිව්. ඩී. අමරදේව", "වික්ටර් රත්නායක", "ජෝර්ජ් විල්ෆ්‍රඩ් අල්විස් නමින් උපන් ආනන්ද සමරකෝන් ශාන්තිනිකේතනයේදී ශිල්ප හැදෑරීය."),
        q("'නමෝ නමෝ මාතා' ලෙස මුලින්ම ලියවුණු ශ්‍රී ලංකා ජාතික ගීය සඳහා මුල් තාලය හා රචනය කළේ කවර වර්ෂයේදීද?", "1940 දී", "1956 දී", "1972 දී", "1877 දී", "1940 දී මහින්ද විද්‍යාලයේ ගුරුවරයෙකු ලෙස සිටියදී ආනන්ද සමරකෝන් මෙය නිර්මාණය කළේය."),
        q("සිංහල ස්වතන්ත්‍ර සරල ගීත කලාවේ ආරම්භක පුරෝගාමියා ලෙස ගෞරවයට පාත්‍ර වන්නේ කවුද?", "ආනන්ද සමරකෝන්", "සී. දොන් බස්තියන්", "පිලිප්පු සිංඤෝ", "විශ්වනාත් ලෞජි", "ඉන්දීය චිත්‍රපට තනු කොපි කිරීමේ රැල්ල නවතා ස්වතන්ත්‍ර තනු නිර්මාණය ඇරඹුවේ ඔහුය."),
        q("'එන්ඩද මැණිකේ', 'විලේ මලක් පිපිලා' සහ 'පොඩි මල් එතනෝ' වැනි ගීත නිර්මාණය කළේ කවුද?", "ආනන්ද සමරකෝන්", "සුනිල් ශාන්ත", "සනත් නන්දසිරි", "නන්දා මාලිනී", "සමරකෝන්ගේ මෙම ගීත සරල බව හා හෙළ ගැමි රසය අපූරුවට ඉස්මතු කළේය."),
        q("සුනිල් ශාන්තයන් උසස් සංගීත අධ්‍යාපනය හැදෑරීමට ඇතුළත් වූ ඉන්දියාවේ සංගීත ආයතනය කුමක්ද?", "ලක්නව්හි භාත්ඛණ්ඩේ (මැරිස්) සංගීත විද්‍යාලය", "චෙන්නායි කලාක්ෂේත්‍රය", "ලන්ඩන් රෝයල් ඇකඩමිය", "බොම්බාය පාර්සි ආයතනය", "බදුලු ප්‍රදේශයේ පියාගෙන් හා පසුව ශාන්තිනිකේතනය හරහා ලක්නව් මැරිස් විද්‍යාලයේදී උපාධි ලැබීය."),
        q("'ඕලු පිපීලා විල ලෙළ දෙනවා' ගීතය ගයා සිංහල ගුවන්විදුලි සංගීතයේ නව යුගයක් ඇරඹූයේ කවුද?", "සුනිල් ශාන්ත", "ආනන්ද සමරකෝන්", "මොහිදීන් බෙග්", "එච්. ආර්. ජෝතිපාල", "1946 දී ගුවන්විදුලිය ඔස්සේ ප්‍රචාරය වූ ඕලු පිපීලා ගීතය අතිශය ජනප්‍රිය විය."),
        q("සුනිල් ශාන්තයන් හා කුමාරතුංග මුනිදාසයන්ගේ 'හෙළ හවුල' අතර තිබූ ප්‍රබල බැඳීම කුමක්ද?", "නිවැරදි හෙළ වහර හා ස්වතන්ත්‍ර හෙළ ගී තනු නිර්මාණය කිරීම", "ඉංග්‍රීසි ගීත පරිවර්තනය කිරීම", "රාග ගී තහනම් කිරීම", "සංස්කෘත භාෂාව පමණක් ගැයීම", "රැපියෙල් තෙන්නකෝන් හා හෙළ හවුලේ පද රචනා සඳහා සුනිල් ශාන්ත මිහිරි හෙළ තනු නිමවීය."),
        q("'රන් වලාකුළු', 'හඳපානේ', 'බෝවිටියා දං පලුකන් වාරේ' වැනි ගීත නිර්මාණය කළ හෙළ ගායන ශිල්පියා කවුද?", "සුනිල් ශාන්ත", "ඩබ්ලිව්. ඩී. අමරදේව", "ගුණදාස කපුගේ", "සෝමදාස ඇල්විටිගල", "සිංහල ජන නාද හා බටහිර සුළු ආභාසයද මුසු කරමින් සුනිල් ශාන්ත මෙම ගීත නිමවීය."),
        q("'හෙළ මිහිර' සහ 'සුනිල් හඬ' යන ගීත පොත් හා පුවත්පත් තුළින් සිංහල ගීත කලාව පෝෂණය කළේ කවුද?", "සුනිල් ශාන්ත", "ආනන්ද සමරකෝන්", "විශ්වනාත් ලෞජි", "සී. දොන් බස්තියන්", "පාසල් සිසුන්ට හා රසිකයන්ට නිවැරදි ගීත ඉගෙන ගැනීමට සුනිල් ශාන්ත ගීත ග්‍රන්ථ ප්‍රකාශයට පත් කළේය."),
        q("වනක්කුවත්තවඩුගේ දොන් ඇල්බට් පෙරේරා යන මුල් නමින් උපත ලැබූ 'හෙළයේ මහා ගාන්ධර්වයා' කවුද?", "පණ්ඩිත් ඩබ්ලිව්. ඩී. අමරදේව", "ආනන්ද සමරකෝන්", "සුනිල් ශාන්ත", "ප්‍රේමසිරි කේමදාස", "ශ්‍රී ලංකාවේ ජාතික සංගීතය ගොඩනැගූ පණ්ඩිත් අමරදේවයන්ගේ මුල් නාමය ඇල්බට් පෙරේරාය."),
        q("'ඇල්බට් පෙරේරා' හට 'අමරදේව' යන අනවර්ථ නාමය ලබා දුන්නේ කවුරුන් විසින්ද?", "මහාචාර්ය එදිරිවීර සරච්චන්ද්‍ර", "මහත්මා ගාන්ධි", "කුමාරතුංග මුනිදාස", "ලෙස්ටර් ජේම්ස් පීරිස්", "භාත්ඛණ්ඩේ විද්‍යාලයට යාමට පෙර සරච්චන්ද්‍රයන් විසින් එතුමාට අමරදේව නාමය තබන ලදී."),
        q("පණ්ඩිත් අමරදේවයන් ගුවන්විදුලිය ඔස්සේ දේශීය සංගීතය හා උත්තර භාරතීය රාග එක්කර නිර්මාණය කළ විශිෂ්ට වැඩසටහන කුමක්ද?", "මධුවන්ති සහ ජන ගායනා වැඩසටහන්", "ටවර් හෝල් නූර්ති සැඳෑව", "වෙස්සන්තර කවි", "සොකරි මණ්ඩපය", "මධුවන්ති හා රස මියුරු වැඩසටහන් තුළින් උසස් ශ්‍රාවක රසිකත්වයක් එතුමා ගොඩනැගීය."),
        q("'සන්නාලියනේ', 'ශාන්ත මේ රෑ යාමේ', 'මින්දද හී සර' වැනි අමරණීය ගීත ගැයූ හා තනු නිමවූයේ කවුද?", "පණ්ඩිත් ඩබ්ලිව්. ඩී. අමරදේව", "සුනිල් ශාන්ත", "ආනන්ද සමරකෝන්", "වික්ටර් රත්නායක", "මහගම සේකර හා අමරදේව සුසංයෝගයෙන් සිංහල සරල ගීතයේ ස්වර්ණමය ගීත බිහිවිය."),
        q("ලක්නව්හි භාත්ඛණ්ඩේ සංගීත ආයතනයේ 'විශාරද' සහ වයලීන් වාද්‍ය ශිල්පය ප්‍රගුණ කළ ශ්‍රී ලාංකික මහාචාර්යවරයා හෝ පණ්ඩිතයා කවුද?", "පණ්ඩිත් ඩබ්ලිව්. ඩී. අමරදේව", "පිලිප්පු සිංඤෝ", "සී. දොන් බස්තියන්", "රොමුලස් ද සිල්වා", "අමරදේවයන් විශිෂ්ට වයලීන වාදකයෙකුද වූ අතර උසස් සම්මාන දිනා ගත්තේය."),
        q("රාජ්‍ය ගෞරව සහ පිලිපීනයේ 'රැමොන් මැග්සේසේ' ජාත්‍යන්තර සම්මානයෙන් පිදුම් ලැබූ ශ්‍රී ලාංකික සංගීතඥයා කවුද?", "පණ්ඩිත් ඩබ්ලිව්. ඩී. අමරදේව", "ප්‍රේමසිරි කේමදාස", "සුනිල් ශාන්ත", "ආනන්ද සමරකෝන්", "2001 වර්ෂයේදී පණ්ඩිත් අමරදේවයන් හට මැග්සේසේ සම්මානය පිරිනැමුණි."),
        q("දේශීය ජන ගී පදනම් කරගෙන ස්වතන්ත්‍ර සිංහල සංගීතයක් ගොඩනැගිය යුතු බව පෙන්වා දුන් 'හෙළ ගී මග' කෘතියේ කර්තෘ කවුද?", "ඩබ්ලිව්. බී. මකුලොළුව", "සී. ද එස්. කුලතිලක", "ආර්. ඒ. චන්ද්‍රසේන", "ප්‍රේමසිරි කේමදාස", "දේශීය ජන ගී විද්‍යාත්මකව විශ්ලේෂණය කළ හෙළ ගී මග මකුලොළුවන්ගේ කෘතියකි."),
        q("ශ්‍රී ලංකාවේ පාසල් විෂය මාලාවට දේශීය ජන ගී හා ගායන පර්යේෂණ හඳුන්වා දීමට පුරෝගාමී වූ අධ්‍යාපනඥයා කවුද?", "ඩබ්ලිව්. බී. මකුලොළුව", "මියාන් තාන්සේන්", "අමීර් ඛුස්රෝ", "පණ්ඩිත් රවි ශංකර්", "අධ්‍යාපන දෙපාර්තමේන්තුවේ ප්‍රධාන සංගීත පරීක්ෂකවරයෙකු ලෙස එතුමා පාසල් සංගීතය දියුණු කළේය."),
        q("'ලංකාවේ සංගීත සම්භවය' හා 'මීටර් පද්ධති' පිළිබඳ ගැඹුරු ජන සංගීත පර්යේෂණ කළ ප්‍රවීණ විද්වතා කවුද?", "සී. ද එස්. කුලතිලක", "ඩබ්ලිව්. බී. මකුලොළුව", "ආනන්ද සමරකෝන්", "සුනිල් ශාන්ත", "සිරිල් ද සිල්වා කුලතිලක ගුවන්විදුලි පර්යේෂණ අංශය හරහා වටිනා ජන සංගීත ග්‍රන්ථ රැසක් ලීවේය."),
        q("සිංහල ජන ගී වල ඇති ශ්‍රැති හා තාල සැකැස්ම විග්‍රහ කරමින් ගුවන්විදුලි සංගීත පර්යේෂණ අංශය මෙහෙයවූයේ කවුද?", "සී. ද එස්. කුලතිලක", "විශ්වනාත් ලෞජි", "මොහොමඩ් ගවුස්", "බී. එස්. පෙරේරා", "කුලතිලකයන් 1970 ගණන්වල ගුවන්විදුලි සංගීත පර්යේෂණ අංශයට නායකත්වය දුන්නේය."),
        q("ශ්‍රී ලංකාවේ බටහිර හා පෙරදිග සංගීත ශිල්පය මුසු කොට 'සිම්ෆනි' හා 'කැන්ටාටා' බිහි කළ 'මාස්ටර්' ලෙස ප්‍රකට සංගීතඥයා කවුද?", "ආචාර්ය ප්‍රේමසිරි කේමදාස", "ආනන්ද සමරකෝන්", "ඩබ්ලිව්. බී. මකුලොළුව", "මොහිදීන් බෙග්", "කේමදාස මාස්ටර් මුහුද, සිහින රැය, පිරිනිවන් මංගල්‍යය වැනි විශිෂ්ට නිර්මාණ කළේය."),
        q("'සැළලිහිණි', 'පිරිනිවන් මංගල්‍යය' හා 'මානසවිල' වැනි විශාල කැන්ටාටා හා ඔපෙරා නිමවූ ශ්‍රී ලාංකේය සංගීතවේදියා කවුද?", "ප්‍රේමසිරි කේමදාස", "වික්ටර් රත්නායක", "සනත් නන්දසිරි", "රෝහණ වීරසිංහ", "බෞද්ධ සාහිත්‍ය හා සමාජ අත්දැකීම් ඔස්සේ කේමදාසයන් කැන්ටාටා හා ඔපෙරා ගොඩනැගීය."),
        q("සිංහල ගීතයට 'ස' නව ප්‍රසංග සංස්කෘතියක් එක් කරමින් ඒකපුද්ගල සංගීත ප්‍රසංග කලාව ඇරඹූයේ කවුද?", "ආචාර්ය වික්ටර් රත්නායක", "ඩබ්ලිව්. ඩී. අමරදේව", "ආනන්ද සමරකෝන්", "සුනිල් ශාන්ත", "1973 ජූලි 20 ඇරඹි 'ස' ප්‍රසංගය මෙරට ඒකපුද්ගල ගීත ප්‍රසංගවල පළමු වැන්නයි."),
        q("ආචාර්ය වික්ටර් රත්නායකයන් 1973 දී ආරම්භ කළ සුප්‍රසිද්ධ ඒකපුද්ගල ගීත ප්‍රසංගය කුමක්ද?", "'ස' ප්‍රසංගය", "ශ්‍රවණ රමණී ප්‍රසංගය", "මධුවන්ති ප්‍රසංගය", "ස්වර්ණ වර්ණ ප්‍රසංගය", "'ස' ප්‍රසංගය දශක ගණනාවක් පුරා 1400කට අධික වාර ගණනක් පැවැත්විණි."),
        q("'පවන' වැනි ප්‍රබුද්ධ ප්‍රසංග මාලා හා ජන හදගැස්ම රැගත් විරෝධාකල්ප හා සරල ගී ගැයූ ප්‍රවීණ ගායිකාව කවුද?", "විශාරද නන්දා මාලිනී", "රුක්මණී දේවි", "ලතා වල්පොල", "ඇන්ජලින් ගුණතිලක", "විශාරද නන්දා මාලිනීයන්ගේ ශ්‍රවණ ආරාධනා, සත්‍යයේ ගීතය හා පවන ප්‍රසංග විශේෂයෙන් ප්‍රකටය."),
        q("'ශ්‍රවණ රමණී' වැනි ශාස්ත්‍රීය හා සරල ගී ප්‍රසංග පවත්වා සරල ගීය පෝෂණය කළ මහාචාර්යවරයා කවුද?", "සංගීත නිපුන් සනත් නන්දසිරි", "විශ්වනාත් ලෞජි", "ආනන්ද සමරකෝන්", "සී. දොන් බස්තියන්", "සෞන්දර්ය කලා විශ්වවිද්‍යාලයේ කුලපති ධූරයද හෙබවූ මහාචාර්ය සනත් නන්දසිරි විශිෂ්ට ශිල්පියෙකි."),
        q("සිංහල සිනමා හා සරල ගීත කලාවේ බටහිර වාද්‍ය භාණ්ඩ සහ පෙරදිග රාග ශිල්පීයව සංයෝජනය කළ 'චන්ද්‍රසේන' සංගීතඥයා කවුද?", "ආර්. ඒ. චන්ද්‍රසේන", "ඩබ්ලිව්. බී. මකුලොළුව", "සුනිල් ශාන්ත", "සරච්චන්ද්‍ර", "ආර්. ඒ. චන්ද්‍රසේනයන් ලලිත කලායතනය හරහා ගෝල බාලයන් රැසක් බිහි කළ ප්‍රවීණයෙකි."),
        q("සිංහල සංගීත වංශකතාවේ 'ගාන්ධර්ව' හා පසුකාලීන රේඩියෝ සිලෝන් ශිල්පීන් පුහුණු කළ 'හේවුඩ්' (Heywood) ආයතනය අද කුමක්ද?", "සෞන්දර්ය කලා විශ්වවිද්‍යාලය", "කොළඹ නාලන්දා විද්‍යාලය", "ටවර් හෝල් රඟහල", "මහනුවර කලා මණ්ඩලය", "රජයේ ලලිත කලායතනය හෙවත් හේවුඩ් ආයතනය පසුව සෞන්දර්ය කලා විශ්වවිද්‍යාලය බවට පත්විය."),
        q("ලලිත කලායතනය හෙවත් හේවුඩ් ආයතනයේ මුල් යුගයේ සංගීත අංශයට නායකත්වය දුන් ප්‍රවීණයා කවුද?", "ලයනල් එදිරිසිංහ", "පිලිප්පු සිංඤෝ", "මොහොමඩ් ගවුස්", "විශ්වනාත් ලෞජි", "ශාන්තිනිකේතනයේ හා භාත්ඛණ්ඩේ අධ්‍යාපනය ලැබූ ලයනල් එදිරිසිංහයන් ප්‍රථම සංගීත විදුහල්පතිවරයෙකි."),
        q("'සඳ කිඳුරු' හා 'ගමන නොනිමෙයි' වැනි සුප්‍රකට නිර්මාණ රචනා කළ හා පියදාස සිරිසේන යුගයෙන් පසු බිහිවූ මහාචාර්ය නන්දදාස කෝදාගොඩ කුමකට සම්බන්ධද?", "ශාස්ත්‍රීය සංගීත රසවින්දනය හා ගී පද රචනය", "නාඩගම් මද්දල වාදනය", "තබ්ලා නිෂ්පාදනය", "බෙර කර්මාන්තය", "සරල ගී හා නාට්‍ය ගී ක්ෂේත්‍රයේ විද්වත් දායකත්වයක් සැපයූ විද්වතෙකි."),
        q("වේදිකාවේ මෙන්ම සිනමාවේ 'රන්සළු', 'දෙලොවක් අතර', 'බඹරු ඇවිත්' වැනි චිත්‍රපට සංගීතවත් කළේ කවර සංගීතඥයන්ද?", "ඩබ්ලිව්. ඩී. අමරදේව හා ප්‍රේමසිරි කේමදාස", "විශ්වනාත් ලෞජි හා පිලිප්පු සිංඤෝ", "රවි ශංකර් හා සාකීර් හුසේන්", "තාන්සේන් හා අමීර් ඛුස්රෝ", "රන්සළු අමරදේවයන් විසින්ද බඹරු ඇවිත් කේමදාසයන් විසින්ද සංගීතවත් කරන ලදී."),
        q("සිංහල සංගීතයට දේශීය හා ශාස්ත්‍රීය පදනමක් දැමීමට දායක වූ 'පියසිරි විජේරත්න' හෝ 'ඩන්ස්ටන් ද සිල්වා' වැන්නවුන්ගේ ක්ෂේත්‍රය කුමක්ද?", "සංගීත අධ්‍යාපනය හා සරල/සිතාර් වාදනය", "වෙස්මුහුණු කැටයම් කලාව", "පාර්සි නාට්‍ය රංගනය", "බටහිර පියානෝ නිෂ්පාදනය", "මෙරට සංගීත ගුරු පරපුර හා රාගධාරී ශාස්ත්‍රීය අධ්‍යාපනය ගොඩනැගීමට එතුමන්ලා දායක වූහ."),
        q("බෞද්ධ බැති ගීත කලාව ඉහළ තලයකට ගෙන ආ 'බුද්ධං සරණං ගච්ඡාමි' වැනි ගීත ගැයූ ජනප්‍රිය ගායකයා කවුද?", "මොහිදීන් බෙග්", "එච්. ආර්. ජෝතිපාල", "සුනිල් ශාන්ත", "ආනන්ද සමරකෝන්", "මොහිදීන් බෙග් මහතා බෞද්ධ ගීත හා චිත්‍රපට පසුබිම් ගායනයෙන් සිංහල සංගීතය පෝෂණය කළේය."),
        q("සිංහල සිනමා පසුබිම් ගායනයේ 'ගීත කෝකිලාවිය' ලෙස හඳුන්වනු ලබන්නේ කවුද?", "කලාශූරී ලතා වල්පොල", "රුක්මණී දේවි", "නන්දා මාලිනී", "මාලිනී බුලත්සිංහල", "දශක ගණනාවක් පුරා චිත්‍රපට ගීත දහස් ගණනක් ගැයූ ලතා වල්පොල මෙසේ හැඳින්වේ."),
        q("ශ්‍රී ලංකාවේ 'ගීත කෝකිලාවිය' ලෙස මුලින්ම හැඳින්වූ නිළිය හා ග්‍රැමෆෝන් ගායිකාව කවුද?", "රුක්මණී දේවි", "ඇනී බොතේජු", "සුජාතා අත්තනායක", "චන්ද්‍රලේඛා පෙරේරා", "ඩේසි රාසම්මා ඩැනියල්ස් හෙවත් රුක්මණී දේවි මුල් යුගයේ සිනමා හා ග්‍රැමෆෝන් ගායිකාවයි."),
        q("භාරතීය ශාස්ත්‍රීය සංගීතයේ හින්දුස්ථානි ඛ්‍යාල් ගායනය ලොව පුරා බැබළවූ 'භාරත රත්න' පණ්ඩිත්වරයෙකු කවුද?", "පණ්ඩිත් බීම්සේන් ජෝෂි", "ආනන්ද සමරකෝන්", "උස්තාද් සාකීර් හුසේන්", "පණ්ඩිත් ශිව්කුමාර් ශර්මා", "කිරානා ඝරානාවේ මහා ගායක පණ්ඩිත් බීම්සේන් ජෝෂි භාරත රත්න සම්මානයෙන් පිදුම් ලැබීය."),
        q("කර්ණාටක සංගීතයේ 'ත්‍රිමූර්ති' (Trinity) ලෙස හඳුන්වනු ලබන ශ්‍රේෂ්ඨ වාග්ගේයකාරවරුන් තිදෙනා කවුද?", "ත්‍යාගරාජ, මුත්තුස්වාමි දීක්ෂිතර්, ශ්‍යාමා ශාස්ත්‍රි", "තාන්සේන්, බෛජු බව්රා, අමීර් ඛුස්රෝ", "භාත්ඛණ්ඩේ, පලුස්කර්, තාගෝර්", "භරතමුනි, මතංග, ශාර්ංගදේව", "18 වන සියවසේ දකුණු ඉන්දීය කර්ණාටක සංගීතය බැබළවූ මහා නිර්මාණකරුවන් තිදෙනා මොවුන්ය."),
        q("භාරතීය ගායක උස්තාද් බඩේ ගුලාම් අලි ඛාන් සහ අමීර් ඛාන් ප්‍රකට වූයේ කුමන ගායන ශෛලියෙන්ද?", "හින්දුස්ථානි ඛ්‍යාල් ගායනය", "බටහිර ඔපෙරා ගායනය", "සිංහල වන්නම් ගායනය", "පාර්සි නූර්ති ගායනය", "පටියාලා ඝරානාවේ බඩේ ගුලාම් අලි ඛාන් සහ ඉන්දෝර් ඝරානාවේ අමීර් ඛාන් ඛ්‍යාල් ගායන මහැදුරෝය."),
        q("ශ්‍රී ලංකාවේ ජන සංගීතය සරල ගීයට ගෙන එමින් 'වන්නම් සරල ගී' හා ගැමි රිද්ම ප්‍රචලිත කළ ප්‍රවීණයා කවුද?", "රෝහණ බැද්දගේ", "විශ්වනාත් ලෞජි", "මොහොමඩ් ගවුස්", "සී. දොන් බස්තියන්", "රාජ සභාවේ වන්නම් හා ගැමි කවි ඇසුරෙන් රෝහණ බැද්දගේ රසවත් සරල ගී නිමවීය."),
        q("ටෙලිනාට්‍ය හා චිත්‍රපට සංගීතයේ 'රෝහණ වීරසිංහ' සංගීතඥයා විශේෂයෙන් හඳුන්වනු ලබන්නේ කුමන දායකත්වයක් සඳහාද?", "මිහිරි ජනප්‍රිය සරල ගී තනු හා පසුබිම් සංගීතය", "පැරණි නාඩගම් පොත් රචනය", "තබ්ලා කර්මාන්තය", "කර්ණාටක මේල 72 නිර්මාණය", "ගීත දහස් ගණනකට සුමිහිරි තනු නිර්මාණය කළ ප්‍රමුඛතම සංගීත අධ්‍යක්ෂවරයෙකි."),
        q("'සඳකඩපහණක කැටයම් ඔපලා' ගීතය ගායනා කළ අතර නව ආරක සරල ගී බිහි කළ ගායකයා කවුද?", "සුනිල් එදිරිසිංහ", "ඩබ්ලිව්. ඩී. අමරදේව", "ආනන්ද සමරකෝන්", "එච්. ආර්. ජෝතිපාල", "වොලී නානායක්කාර පද රචනයට වික්ටර් රත්නායක තනු නිමවූ මෙම ගීතය ගැයුවේ සුනිල් එදිරිසිංහය."),
        q("සිංහල ගීත සාහිත්‍යයේ 'මහගම සේකර' සහ 'මඩවල එස්. රත්නායක' යන විද්වතුන්ගේ ප්‍රධාන දායකත්වය කුමක්ද?", "සාහිත්‍යමය ගුණයෙන් පිරි උසස් ගී පද රචනය", "සිතාර් නිෂ්පාදනය", "ගැටබෙර වාදනය", "නූර්ති ශාලා ඉදිකිරීම", "සිංහල සරල ගීයට ගැඹුරු කාව්‍යමය ගීත රචනා සම්ප්‍රදායක් එතුමන්ලා එක් කළහ."),
        q("කැන්ටාටා හා සිංහල චිත්‍රපට සංගීතයේ නව මාවත් සොයා ගිය 'සෝමදාස ඇල්විටිගල' සංගීතඥයා අධ්‍යාපනය ලැබුවේ කොහේද?", "ලක්නව් භාත්ඛණ්ඩේ සංගීත ආයතනයේ", "පැරිස් කොන්සර්වේටරියේ", "ටෝකියෝ විශ්වවිද්‍යාලයේ", "ඔක්ස්ෆර්ඩ් විශ්වවිද්‍යාලයේ", "ලක්නව්හි භාත්ඛණ්ඩේ ආයතනයේ සිප් සතර හදාරා මෙරට සංගීතය පෝෂණය කළේය."),
        q("භාරතීය ශාස්ත්‍රීය සංගීතයේ 'මෛහාර් ඝරානාව' (Maihar Gharana) බිහි කළ පුරෝගාමී මහා ගුරුවරයා කවුද?", "උස්තාද් අලවුද්දීන් ඛාන්", "පණ්ඩිත් භාත්ඛණ්ඩේ", "අමීර් ඛුස්රෝ", "වෙන්කටමුඛී", "පණ්ඩිත් රවි ශංකර්, අලි අක්බර් ඛාන් සහ පන්නාලාල් ඝෝෂ්ගේ ගුරුවරයා උස්තාද් අලවුද්දීන් ඛාන්ය."),
        q("'ධවල භූමි' හෝ දේශීය ශබ්ද රසය විහිදුවන පරිදි ජන ගී ආශ්‍රිතව 'මිහිඳු සන්දේශය' වැනි ගීත නාටක ලියූවන් අතර වැදගත් ශිල්පියෙකු කවුද?", "විසෙන්ති පෙරේරා / ඩබ්ලිව්. බී. මකුලොළුව", "මියාන් තාන්සේන්", "භරතමුනි", "වෙන්කටමුඛී", "ජන ගී ආභාසය රැගත් සංගීත නාටක මගින් දේශීය සංගීත අනන්‍යතාව සුරැකිණි."),
        q("ලංකාවේ බෞද්ධ සංගීත ඉතිහාසයේ 'පිරිත් සජ්ඣායනය' තුළ දක්නට ලැබෙන ප්‍රධාන ස්වර ලක්ෂණය කුමක්ද?", "සාම වේදයට සමානව සීමිත ස්වර තුනක් හෝ හතරක් තුළ ගැයීම", "සප්තක තුනම වේගයෙන් ගැයීම", "තබ්ලාව හා සිතාරය සමඟ ගැයීම", "බටහිර කෝඩ්ස් යෙදීම", "පිරිත් සජ්ඣායනය තුළ සාම්ප්‍රදායික ත්‍රිස්වර ආදී සංයමශීලී ස්වර පරාසයක් පවතී."),
        q("මහනුවර යුගයේ රචනා වූ දහඅට වන්නම් පිළිබඳව සඳහන් කරන ඓතිහාසික මූලාශ්‍රවල ඒවා රචනා වූයේ කුමන රජුගේ කාලයේදැයි කියැවේද?", "ශ්‍රී වීර පරාක්‍රම නරේන්ද්‍රසිංහ රජුගේ කාලයේ", "දුටුගැමුණු රජුගේ කාලයේ", "මහා පරාක්‍රමබාහු රජුගේ කාලයේ", "විජය රජුගේ කාලයේ", "කුණ්ඩසාලේ නරේන්ද්‍රසිංහ රජ සමයේ ගණිතාලංකාර ආදී පඬිවරුන් වන්නම් රචනා කළ බව සඳහන් වේ."),
        q("ශ්‍රී ලංකාවේ පැරණි සාහිත්‍ය ග්‍රන්ථයක් වන 'සැළලිහිණි සංදේශයේ' සඳහන් වන නෘත්‍ය ගීත හා වාද්‍ය භාණ්ඩ තොරතුරු කුමන යුගයක තත්ත්වය පෙන්වයිද?", "කෝට්ටේ යුගයේ සංගීත කලාව", "වික්ටෝරියානු බ්‍රිතාන්‍ය යුගය", "20 වන සියවසේ සිනමා යුගය", "රාවණා යුගය", "තොටගමුවේ ශ්‍රී රාහුල හිමියන්ගේ සැළලිහිණිය කෝට්ටේ යුගයේ පංචතූර්ය නාදය ගැන සාක්ෂි සපයයි."),
        q("කෝට්ටේ යුගයේ 'කාව්‍යශේඛරය' හා 'ගුත්තිල කාව්‍යය' තුළින් පෙනී යන මෙරට පැරණි සංගීත දැනුම කුමක්ද?", "සප්ත ස්වර, රාග, තාල හා වීණා වාදන ශාස්ත්‍රය", "පියානෝ හා සැක්සෆෝන් වාදනය", "ඩිජිටල් ශබ්ද පටිගත කිරීම", "පාර්සි නූර්ති නාට්‍ය", "වෑත්තෑවේ හිමියන්ගේ ගුත්තිල කාව්‍යයේ සප්ත තන්ත්‍රී වීණාව හා භාරතීය සංගීත ශාස්ත්‍රය වර්ණනා වේ."),
        q("පොළොන්නරු යුගයේ ගල් විහාරයේ හා සඳකඩපහණ ආසන්න කැටයම්වලින් හෙළිවන පැරණි සංගීත තොරතුර කුමක්ද?", "පුරාණ බෙර, හක්ගෙඩි, තාලම්පට හා නැටුම් භාවිතය", "ග්‍රැමෆෝන් තැටි වාදනය", "හාමෝනියම් වාදනය", "පෘතුගීසි වයලීන් වාදනය", "දඹදෙණි හා පොළොන්නරු කැටයම් තුළ පංචතූර්ය වාද්‍ය භාණ්ඩ මැනවින් නිරූපිතය."),
        q("ශ්‍රී ලංකාවේ 'ගීත සාහිත්‍යයේ' භාෂාව පිළිබඳව සැලකීමේදී ශ්‍රී චන්ද්‍රරත්න මානවසිංහයන්ගේ විශිෂ්ටත්වය කුමක්ද?", "සංගීතමය වචන රිද්මයෙන් පිරි සරල ගී හා නාට්‍ය ගී රචනය", "ඉංග්‍රීසි පද්‍ය පරිවර්තනය පමණක්", "තබ්ලා කර්මාන්තය දියුණු කිරීම", "කෝලම් වෙස්මුහුණු සෑදීම", "'මනෝහාරි', 'වැලිතල අතරේ' වැනි අතිශය කාව්‍යමය ගීත මානවසිංහයන් රචනා කළේය."),
        q("'පාත ඉඳන් අපි ආවේ' හා 'මුළු ගමටම එක අවුරුද්දයි' වැනි ගීත හරහා ගැමි ජීවිතය සංගීතවත් කළ කලාකරුවෙකු කවුද?", "සී. ටී. ප්‍රනාන්දු හෝ ආර්. මුත්තුසාමි", "මියාන් තාන්සේන්", "භරතමුනි", "වෙන්කටමුඛී", "සී. ටී. ප්‍රනාන්දු මහතා බටහිර හා දේශීය හුරුව මුසු කරමින් සරල ගීත ජනප්‍රිය කළේය."),
        q("සිංහල සංගීතයේ 'බයිලා' සහ 'කපිරිඤ්ඤා' රිද්ම රටා මෙරටට එක්වීමට මුල් වූ විදේශීය බලපෑම කුමක්ද?", "පෘතුගීසි හා අප්‍රිකානු (කාපිරි) ආභාසය", "චීන හා ජපන් ආභාසය", "හින්දුස්ථානි ධ්‍රැපද් ආභාසය", "රුසියානු ඔපෙරා ආභාසය", "16 වන සියවසෙන් පසු පෘතුගීසීන් හා ඔවුන් ගෙන ආ කාපිරි ජනයාගෙන් 6/8 රිද්ම ලැබුණි."),
        q("'කපිරිඤ්ඤා' හා දේශීය ජන රිද්ම ඇසුරෙන් බිහිවූ 'වොලී බැස්ටියන්' ගේ සංගීත දායකත්වය කුමක්ද?", "කෝරස් බයිලා ගීත කලාවේ පුරෝගාමියා වීම", "ශාස්ත්‍රීය ඛ්‍යාල් ගායනය", "පිරිත් සජ්ඣායනය", "සිතාර් වාදනය", "මුල් යුගයේ ජනප්‍රිය කෝරස් බයිලා ගීත නිර්මාණය කරමින් වොලී බැස්ටියන් කැපී පෙනුණි."),
        q("1960 - 1970 දශකවල සිංහල ගීතයට පෙරදිග රාගවලට අමතරව වෙනත් රටවල ජන හා සරල නාද එක්කර ජනප්‍රිය කළ ගායකයා කවුද?", "ක්ලැරන්ස් විජේවර්ධන", "පිලිප්පු සිංඤෝ", "විශ්වනාත් ලෞජි", "ශාර්ංගදේව", "ක්ලැරන්ස් විජේවර්ධන සිංහල පොප් හා කණ්ඩායම් සංගීතයේ පුරෝගාමියා ලෙස සැලකේ."),
        q("ශ්‍රී ලංකාවේ 'සිංහල පොප්' (Sinhala Pop) හා කණ්ඩායම් සංගීතයේ පියා ලෙස සැලකෙන සංගීතවේදියා කවුද?", "ක්ලැරන්ස් විජේවර්ධන", "ආනන්ද සමරකෝන්", "පණ්ඩිත් අමරදේව", "ඩබ්ලිව්. බී. මකුලොළුව", "මූන්ස්ටෝන්ස් හා ගෝල්ඩන් චයිම්ස් තුළින් ඉලෙක්ට්‍රික් ගිටාරය සහිත සිංහල කණ්ඩායම් සංගීතය බිහි කළේය."),
        q("'සඳ තනිවෙලා අහසේ', 'මංගෝ කලු නැන්දේ' වැනි ගී නිමවූ ක්ලැරන්ස් විජේවර්ධනයන්ගේ සංගීත ශෛලියේ විශේෂත්වය කුමක්ද?", "බටහිර ගිටාර් හාමනි සමඟ දේශීය සුමිහිරි තනු මුසු කිරීම", "තබ්ලාව පමණක් වැයීම", "වේදිකා නාඩගම් රචනා කිරීම", "සංස්කෘත ශ්ලෝක ගායනය", "බටහිර වාද්‍ය භාණ්ඩ භාවිත කළද එතුමාගේ තනු තුළ සිංහල ජන හදගැස්ම රැඳී තිබුණි."),
        q("ගුවන්විදුලි සංස්ථාවේ 'ජන සංගීත' වැඩසටහන් මෙහෙයවමින් හා ජන ගී සංරක්ෂණයට දායක වූ ප්‍රවීණයන් අතර ප්‍රධාන වන්නේ කවුද?", "සී. ද එස්. කුලතිලක හා ලයනල් රන්වල", "මියාන් තාන්සේන්", "අමීර් ඛුස්රෝ", "පිලිප්පු සිංඤෝ", "ලයනල් රන්වල මහතා ජන ගී පර්යේෂණයෙන් පමණක් නොව ඒවා නව පරපුරට සජීවීව ඉදිරිපත් කළේය."),
        q("'අහසේ ඉන්නවලු' හා 'ගම අවුලඤ්ඤං' වැනි ජන ගී ඇසුරෙන් නූතන ගායනා කළ 'තලමල පිපිලා' කණ්ඩායමේ නියමුවා කවුද?", "ලයනල් රන්වල", "ආනන්ද සමරකෝන්", "සුනිල් ශාන්ත", "සී. දොන් බස්තියන්", "ජන නාද හා රිද්ම ආරක්ෂා කරමින් ප්‍රසංග වේදිකාවට ගෙන ඒමට ලයනල් රන්වලයන් මුල් විය."),
        q("1948 නිදහස ලැබීමත් සමඟ මෙරට සංගීත ක්ෂේත්‍රයේ ඇතිවූ ප්‍රධාන ප්‍රවණතාව කුමක්ද?", "ජාතික අනන්‍යතාවක් සහිත ස්වතන්ත්‍ර සිංහල සංගීතයක් ගොඩනැගීම", "සියලු දේශීය භාණ්ඩ විනාශ කිරීම", "දෙමළ නාඩගම් පමණක් රඟදැක්වීම", "බටහිර ගීත පමණක් පාසල්වල ඉගැන්වීම", "ගුවන්විදුලිය, අධ්‍යාපනය හා නාට්‍ය ඔස්සේ ස්වාධීන ශ්‍රී ලාංකේය සංගීතයක් බිහිවන්නට විය."),
        q("ශ්‍රී ලංකාවේ පාසල් අධ්‍යාපනයේ ප්‍රථම වරට පෙරදිග සංගීතය විධිමත් විෂයයක් ලෙස ව්‍යාප්ත වූයේ කවර කාලවකවානුවේදීද?", "20 වන සියවසේ මැද භාගයේ (1940-1960 දශක)", "15 වන සියවසේ කෝට්ටේ යුගයේ", "18 වන සියවසේ මුල් භාගයේ", "21 වන සියවසේ අග භාගයේ", "නිදහස් අධ්‍යාපනය හා රජයේ සංගීත පරීක්ෂකවරුන්ගේ මැදිහත්වීමෙන් පාසල් පද්ධතියට සංගීතය එක්විය."),
        q("පෙරදිග සංගීත ඉතිහාසයේ 'භක්ති සංගීත ව්‍යාපාරය' (Bhakti Movement) මගින් ඉන්දියාවේ ප්‍රචලිත වූ ගීත වර්ග මොනවාද?", "භජන්, කීර්තන් සහ අභංග", "සිම්ෆනි හා ඔපෙරා", "කපිරිඤ්ඤා හා බයිලා", "ගසල් හා රැප්", "මීරාබායි, කබීර්, සූර්දාස් හා තුල්සිදාස් වැනි භක්තිවන්තයෝ පොදු බසින් භජන් ගී ගැයූහ."),
        q("උත්තර භාරතීය ශාස්ත්‍රීය සංගීතයේ 'ඝරානා' (Gharana) යන වචනයෙන් අදහස් කරන්නේ කුමක්ද?", "පරම්පරාගතව එන සුවිශේෂී සංගීත ගුරු කුලය හෝ ශෛලිය", "සංගීත භාණ්ඩ සාදන කම්හල", "රාගයක් ගයන වේලාව", "තාලයක මාත්‍රා ගණන", "ග්වාලියර්, ආග්‍රා, කිරානා, පටියාලා ආදී වශයෙන් ගුරු-ශිෂ්‍ය පරපුරෙන් එන ශෛලීන් ඝරානා වේ."),
        q("හින්දුස්ථානි ඛ්‍යාල් ගායන සම්ප්‍රදායේ පැරණිතම හා මව් ඝරානාව ලෙස සැලකෙන්නේ කුමක්ද?", "ග්වාලියර් ඝරානාව (Gwalior Gharana)", "පටියාලා ඝරානාව", "කිරානා ඝරානාව", "බෙනාරස් ඝරානාව", "බොහෝ උත්තර භාරතීය ගුරු කුලවල ආරම්භය සිදුවූ පැරණිතම ඛ්‍යාල් ඝරානාව ග්වාලියර් ඝරානාවයි."),
        q("සුප්‍රකට භාරතීය වයලීන වාදක පරපුරට අයත් දකුණු ඉන්දීය මහා කලාකරුවෙකු වන්නේ කවුද?", "ලාල්ගුඩි ජයරාමන් (හෝ එල්. සුබ්‍රමනියම්)", "පිලිප්පු සිංඤෝ", "ජෝන් ද සිල්වා", "විශ්වනාත් ලෞජි", "ලාල්ගුඩි ජයරාමන්, ටී. එන්. ක්‍රිෂ්ණන් සහ එල්. සුබ්‍රමනියම් ලෝක ප්‍රකට ඉන්දීය වයලීන වාදකයෝය."),
        q("දක්ෂිණ භාරතීය කර්ණාටක ගායනය ලොව පුරා ගෞරවයට පත් කළ 'භාරත රත්න' සම්මානලාභී ගායිකාව කවුද?", "එම්. එස්. සුබ්බුලක්ෂ්මි", "ලතා වල්පොල", "රුක්මණී දේවි", "නන්දා මාලිනී", "එක්සත් ජාතීන්ගේ සංවිධානයේ පවා ගී ගැයූ එම්. එස්. සුබ්බුලක්ෂ්මි කර්ණාටක සංගීතයේ අග්‍රගණ්‍ය ශිල්පිනියයි."),
        q("ලෝක ප්‍රකට භාරතීය චිත්‍රපට හා සම්භාව්‍ය පසුබිම් ගායිකාවක ලෙස 'ඉන්දියාවේ ගීත කෝකිලාව' ලෙස විරුදාවලි ලැබුවේ කවුද?", "ලතා මංගේෂ්කර්", "සුබ්බුලක්ෂ්මි", "බේගම් අක්තාර්", "කිෂෝරි අමෝන්කර්", "ලතා මංගේෂ්කර් මහත්මිය භාෂා ගණනාවකින් ගීත දහස් ගණනක් ගයා භාරත රත්න සම්මානය ද ලැබුවාය."),
        q("හින්දුස්ථානි ඛ්‍යාල් සංගීතයේ 'කෝකිලාව' සහ ජයිපූර්-අත්‍රෞලි ඝරානාවේ ශ්‍රේෂ්ඨ ගායිකාවක වූයේ කවුද?", "පණ්ඩිතා කිෂෝරි අමෝන්කර්", "ලතා වල්පොල", "රුක්මණී දේවි", "සෝමලතා සුබසිංහ", "භාවපූර්ණ රාග ගායනයෙන් යුගයක් බැබළවූ කිෂෝරි අමෝන්කර් ජයිපූර් ඝරානාවේ ප්‍රමුඛ ගායිකාවකි."),
        q("භාරතීය සංගීතයේ 'ධ්‍රැපද්' ගායන ශෛලිය හා බැඳුණු ප්‍රධාන පරම්පරාව කුමක්ද?", "ඩාගර් පරම්පරාව (Dagarvani)", "සේනියා පරපුර පමණක්", "නාඩගම් පරපුර", "ග්‍රැමෆෝන් පරපුර", "ඉපැරණි ධ්‍රැපද් සම්ප්‍රදාය නොනැසී රැකගැනීමට ඩාගර් පරපුර විශාල මෙහෙයක් ඉටු කළේය."),
        q("ශ්‍රී ලංකාවේ 'ගීත රචකයන් හා තනු නිර්මාපකයන්' අතර වීණා හා සිතාර් වාදනයෙන්ද දායක වූ විශාරද 'ඩී. ආර්. නානායක්කාර' හෝ සංගීත විශාරද 'ටියුඩර් ජයශාන්ත' වැන්නන් කුමකට ප්‍රසිද්ධද?", "රාගධාරී ශාස්ත්‍රීය අධ්‍යාපනය හා සරල ගී වාදනය", "පාර්සි නාට්‍ය අධ්‍යක්ෂණය", "රූකඩ නැටවීම", "බෙර කර්මාන්තය", "මෙරට සංගීත විශාරදවරුන් පරපුරක් බිහිකරමින් පාසල් හා ගුවන්විදුලිය පෝෂණය කළහ."),
        q("පසුකාලීනව ශ්‍රී ලංකාවේ ජනප්‍රිය සරල ගීයට වඩා ගැඹුරු කාව්‍යමය රසයක් ගෙන ආ 'රත්න ශ්‍රී විජේසිංහ' ගේ භූමිකාව කුමක්ද?", "සංවේදී හා සාහිත්‍යමය ගී පද රචනය", "තබ්ලා වාදනය", "නාඩගම් මද්දල නිෂ්පාදනය", "වේදිකා ආලෝකකරණය", "ජන වහර හා උපමා රූපක භාවිතයෙන් අර්ථපූර්ණ සිංහල ගීත රැසක් එතුමා රචනා කර ඇත."),
        q("බටහිර සම්භාව්‍ය සංගීතයේ 'සංධ්වනි' (Symphony) සංගීතයේ ප්‍රධානතම කීර්තිමත් නිර්මාතෘවරුන් අතරින් කෙනෙකු නම් කරන්න.", "ලුඩ්විග් වෑන් බීතෝවන් (හෝ මෝසාර්ට්)", "මියාන් තාන්සේන්", "අමීර් ඛුස්රෝ", "විෂ්ණු නාරායන් භාත්ඛණ්ඩේ", "මෝසාර්ට්, බීතෝවන් හා බාක් බටහිර සම්භාව්‍ය සංගීතයේ අග්‍රගණ්‍ය සංගීතඥයෝ වෙති."),
        q("බිහිරි බවට පත්ව සිටියදීත් ලෝක ප්‍රකට 9 වන සංධ්වනිය (Ninth Symphony) නිර්මාණය කළ බටහිර සංගීතඥයා කවුද?", "බීතෝවන් (Ludwig van Beethoven)", "මෝසාර්ට්", "ජෝන් සෙබස්තියන් බාක්", "ෆ්‍රෙඩ්රික් චොපින්", "ශ්‍රවණාබාධිත වූ පසුවත් මනසින් ස්වර හඳුනාගෙන බීතෝවන් විශිෂ්ට සංධ්වනි රචනා කළේය."),
        q("බටහිර සංගීතයේ 'බැරොක් යුගයේ' (Baroque Era) මහා පියා හා ප්‍රධාන නිර්මාතෘ ලෙස සැලකෙන්නේ කවුද?", "ජෝන් සෙබස්තියන් බාක් (J. S. Bach)", "බීතෝවන්", "රවි ශංකර්", "එඩ්වඩ් එල්ගාර්", "සංකීර්ණ ස්වර සංයෝජන (Fugue) රචනා කළ ජේ. එස්. බාක් බැරොක් යුගයේ ප්‍රමුඛයාය."),
        q("ශ්‍රී ලංකාවේ බෞද්ධ පන්සල් ආශ්‍රිතව සාම්ප්‍රදායික සංගීතය හා නර්තනය ආරක්ෂා වී පැවතීමට ප්‍රධාන හේතුව කුමක්ද?", "පෙරහැර, තේවා හා ආගමික පූජා වතාවත් සමඟ බැඳී තිබීම", "විදේශීය ආක්‍රමණ නිසා රජයෙන් තහනම් කිරීම", "රූපවාහිනී තරඟ නිසා", "ග්‍රැමෆෝන් තැටි නිෂ්පාදනය නිසා", "දළදා මාලිගාව ඇතුළු විහාරස්ථානවල තේවා වතාවත් හරහා පංචතූර්ය නාදය අඛණ්ඩව රැකුණි."),
        q("ඉන්දියාව හා ශ්‍රී ලංකාව අතර පැවති සංස්කෘතික සම්බන්ධතා නිසා මෙරට සංගීතයට සිදුවූ ප්‍රධාන යහපත කුමක්ද?", "ශාස්ත්‍රීය රාග, තාල හා වාද්‍ය භාණ්ඩ දැනුම හුවමාරු වීම", "දේශීය ජන ගී සම්පූර්ණයෙන් අමතක වීම", "සිංහල භාෂාව වෙනුවට හින්දි පමණක් ගැයීම", "බෙර වර්ග තහනම් වීම", "උත්තර හා දක්ෂිණ භාරතීය ශාස්ත්‍රීය ශිල්ප ක්‍රමවලින් මෙරට සංගීතය පෝෂණය විය.")
    )
}
